def relay_balanced_cuts(adjustments: list[int]) -> int:
    total = sum(adjustments)
    left = 0
    answer = 0
    for i in range(len(adjustments) - 1):
        left += adjustments[i]
        if left * 2 == total:
            answer += 1
    return answer

