def relay_balanced_cuts(adjustments: list[int]) -> int:
    answer = 0
    for cut in range(1, len(adjustments)):
        left = 0
        right = 0
        for i in range(cut):
            left += adjustments[i]
        for i in range(cut, len(adjustments)):
            right += adjustments[i]
        if left == right:
            answer += 1
    return answer
